/**
 * Booking Types — Sawaa Dashboard
 *
 * Entity shapes are DERIVED from the committed OpenAPI snapshot
 * (`lib/types/api.generated.ts`, regenerated by `pnpm openapi:sync`), so a
 * backend response change shows up here as a type error instead of drifting
 * silently. Types that describe request payloads or UI vocabulary stay local.
 *
 * Vocabulary note: the dashboard UI says `individual` while the wire says
 * `in_person` (see modules/bookings/booking-row.mapper.ts). Both are kept
 * below explicitly; the mismatch is tracked in the maintainability roadmap.
 */
import type { components } from "@/lib/types/api.generated"

type Schemas = components["schemas"]

/* ─── Enums (wire vocabulary for responses) ─── */
export type BookingStatus =
  | "pending"
  | "pending_group_fill"
  | "awaiting_payment"
  | "deposit_paid"
  | "confirmed"
  | "completed"
  | "cancelled"
  | "no_show"
  | "expired"
  | "cancel_requested"
export type RefundType = "full" | "partial" | "none"
export type CancelledBy = "client" | "employee" | "admin" | "system"
/** UI/request vocabulary (create payload, filters). Wire rows say `in_person`. */
export type BookingType = "individual" | "group" | "walk_in"
export type BookingRowType = "in_person" | "group" | "walk_in"
export type DeliveryType = "IN_PERSON" | "ONLINE"
export type BookingSource = "RECEPTION" | "ONLINE"

/* ─── Entities (derived from OpenAPI) ─── */
export type BookingClient = Schemas["BookingRowClientDto"]
export type BookingEmployee = Schemas["BookingRowEmployeeDto"]
export type BookingService = Schemas["BookingRowServiceDto"]
export type BookingPayment = Pick<
  Schemas["BookingRowPaymentDto"],
  "id" | "amount" | "method" | "status" | "totalAmount"
> &
  Partial<Omit<Schemas["BookingRowPaymentDto"], "id" | "amount" | "method" | "status" | "totalAmount">>
export type HistoricalBookingPayment = Schemas["BookingRowHistoricalPaymentDto"]
export type BookingInvoice = Schemas["BookingRowInvoiceDto"]
export type BookingPackageFunding = Schemas["BookingRowPackageFundingDto"]

export interface RescheduledFrom {
  id: string
  date: string
  startTime: string
}

/* ─── Main Booking ─── */

type BookingRow = Schemas["BookingRowDto"]

/**
 * Dashboard-facing booking row. Every field comes from the OpenAPI snapshot
 * (`BookingRowDto`), so a backend field addition/removal is a type error here.
 *
 * Fields below are narrowed/reshaped to the vocabulary the dashboard already
 * uses; each one is a documented difference from the wire contract (asserted
 * by `apps/dashboard/test/unit/lib/booking-type-contract.spec.ts`):
 *  - `date`/`startTime`/`endTime`: the API may return null for historic rows,
 *    the dashboard assumes a valid schedule and formats them directly.
 *  - `type`: wire says `in_person`; UI and create payloads say `individual`.
 *  - `deliveryType`: wire is lower-case; forms/tests use `IN_PERSON`/`ONLINE`
 *    and normalize at render time (`lib/booking-delivery.ts`).
 *  - `cancelledBy`/`suggestedRefundType`: documented as `string`; the narrower
 *    unions drive exhaustive status maps.
 *  - `employee`/`service`: non-null as before (the list/detail UI relies on it).
 *  - `payment`: five required fields; the rest stay optional so fixtures and
 *    partial projections keep working.
 *  - `lateEntryRecordedByName`: not produced by the API; kept for a legacy
 *    component that falls back to `lateEntryRecordedBy`.
 *  - `employeeNameSnapshot`/`departmentNameSnapshot`: dropped from the old
 *    hand-written entity; the API never sent them and nothing reads them.
 */
type NarrowedBookingKeys =
  | "clientId"
  | "isLateEntry"
  | "date"
  | "startTime"
  | "endTime"
  | "type"
  | "deliveryType"
  | "cancelledBy"
  | "suggestedRefundType"
  | "employee"
  | "service"
  | "payment"

export type Booking = Omit<BookingRow, NarrowedBookingKeys> & {
  /** Legacy rows/imports may have no client; the UI branches on this. */
  clientId: string | null
  /** Optional in the dashboard's view; the wire always sends it. */
  isLateEntry?: boolean
  date: string
  startTime: string
  endTime: string
  type: BookingRowType | BookingType
  deliveryType: DeliveryType | null
  cancelledBy: CancelledBy | null
  suggestedRefundType: RefundType | null
  employee: BookingEmployee
  service: BookingService
  payment: BookingPayment | null
  lateEntryRecordedByName?: string | null
}

/* Compile-time guard: every field the API sends exists on `Booking`. */
type MissingFromBooking = Exclude<keyof BookingRow, keyof Booking>
const _bookingCoversWireShape: MissingFromBooking extends never ? true : MissingFromBooking = true
void _bookingCoversWireShape

/* ─── Query / Request DTOs ─── */

export interface BookingListQuery {
  sortOrder?: "asc" | "desc"
  page?: number
  limit?: number
  status?: BookingStatus
  type?: BookingType
  deliveryType?: DeliveryType
  employeeId?: string
  clientId?: string
  dateFrom?: string
  dateTo?: string
  search?: string
  isLateEntry?: boolean
  isGuest?: boolean
}

export interface CreateBookingPayload {
  clientId?: string
  employeeId: string
  serviceId: string
  type: BookingType
  deliveryType: DeliveryType
  durationOptionId?: string
  date: string
  startTime: string
  notes?: string
  payAtClinic?: boolean
  branchId?: string
  couponCode?: string
}

export interface ReschedulePayload {
  date?: string
  startTime?: string
}

/** Wire format of the backend RefundType enum (uppercase). */
export type RefundDecision = "FULL" | "PARTIAL" | "NONE"

export interface CancelApprovePayload {
  approverNotes?: string
  refundType?: RefundDecision
  /** Halalas — only sent when refundType is PARTIAL. */
  refundAmount?: number
}

export interface CancelRejectPayload {
  adminNotes?: string
}

export type CancellationReason =
  | "CLIENT_REQUESTED"
  | "EMPLOYEE_UNAVAILABLE"
  | "NO_SHOW"
  | "SYSTEM_EXPIRED"
  | "OTHER"

export interface AdminCancelPayload {
  reason: CancellationReason
  cancelNotes?: string
}

export interface EmployeeCancelPayload {
  reason: string
}

export interface CancelRequestPayload {
  reason?: string
}

export interface ClientReschedulePayload {
  date?: string
  startTime?: string
}

/* ─── Stats ─── */

export interface BookingStats {
  total: number
  confirmed: number
  pending: number
  completed: number
  cancelled: number
  cancelRequested: number
  noShow: number
  expired: number
}
